// Se llama cuando ENTRA en contacto con otro colisionador físico
void OnCollisionEnter(Collision collision)
{
    Debug.Log("Chocó con: " + collision.gameObject.name);
    // collision.contacts → puntos de contacto
    // collision.relativeVelocity → velocidad relativa del impacto
}

// Se llama cada frame mientras SIGUE en contacto
void OnCollisionStay(Collision collision)
{
    // Útil para: daño continuo al estar aplastado contra una pared
}

// Se llama cuando SE SEPARA del colisionador
void OnCollisionExit(Collision collision)
{
    // Útil para: detectar cuándo el jugador toca el suelo y lo deja
}

// Se llama cuando ENTRA en la zona trigger
void OnTriggerEnter(Collider other)
{
    if (other.CompareTag("Player"))
    {
        // El jugador entró a la zona
        ActivarCheckpoint();
    }
}

// Se llama cada frame mientras PERMANECE dentro del trigger
void OnTriggerStay(Collider other)
{
    // Útil para: daño de zona venenosa por segundo
    vida -= danoPorSegundo * Time.deltaTime;
}

// Se llama cuando SALE de la zona trigger
void OnTriggerExit(Collider other)
{
    // Útil para: apagar efectos al salir de una zona de fuego
}

