        estaEnElSuelo = true;
}

// Objeto A: Jugador
// - Rigidbody (no kinematic)
// - Capsule Collider (isTrigger = false)

// Objeto B: Moneda
// - Circle Collider 2D (isTrigger = true)
// - Script con OnTriggerEnter2D

// Objetivo: detectar cuando el jugador DEJA de estar en una zona de niebla
void OnTriggerEnter(Collider other)
{
    if (other.CompareTag("Player"))
        QuitarEfectoNiebla();
}

